    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int m = (int) in.nval;
        int[][] edges = new int[m][2];
        for (int i = 0; i < m; i++) {
            in.nextToken(); edges[i][0] = (int) in.nval;
            in.nextToken(); edges[i][1] = (int) in.nval;
        }
        in.nextToken();
        int s = (int) in.nval;
        in.nextToken();
        long d = (long) in.nval;
        int[][] res = withinDistance(n, edges, s, d);
        StringBuilder sb = new StringBuilder();
        sb.append(res.length).append("\n");
        for (int[] p : res) sb.append(p[0]).append(" ").append(p[1]).append("\n");
        System.out.print(sb);
    }
}
